import { Dependency } from './dependency';
import { Subtask } from './subtask'; // Import Subtask from its own file
import { Tag } from './tag';
import { Topic } from './topic';
import { User } from './user';

export interface TaskBase {
    name: string;
    description?: string;
    project_id: number;
    owner_id: number;
    promoter_id?: number | null;
    status: string;
    priority?: string;
    start_date?: string;
    end_date?: string; // Backend uses 'end_date'
    due_date?: string; // Helper for frontend if needed, mapped from end_date
    progress?: number;
}

export interface TaskCreate extends TaskBase {
    assignee_ids?: number[];
    tag_ids?: number[];
    topic_ids?: number[];
}

export interface TaskUpdate extends Partial<TaskBase> {
    assignee_ids?: number[];
    tag_ids?: number[];
    topic_ids?: number[];
}

export interface Task extends TaskBase {
    id: string | number;
    created_at?: string;
    updated_at?: string;
    subtasks?: Subtask[];
    assignees?: User[];
    dependencies_as_prerequisite?: Dependency[];
    dependencies_as_dependent?: Dependency[];
    tags?: Tag[];
    topics?: Topic[];
}

import { Dependency } from './dependency';
import { Tag } from './tag';
import { Topic } from './topic';

export interface SubtaskBase {
    name: string;
    description?: string;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    progress?: number;
    status: string;
}

export interface SubtaskCreate extends SubtaskBase {
    tag_ids?: number[];
    topic_ids?: number[];
}

export interface Subtask extends SubtaskBase {
    id: number;
    parent_task_id?: number; // Nullable if nested under another subtask
    parent_subtask_id?: number; // New field for nesting
    created_at?: string;
    updated_at?: string;
    tags?: Tag[];
    topics?: Topic[];
    dependencies_as_prerequisite?: Dependency[];
    dependencies_as_dependent?: Dependency[];
    nested_subtasks?: Subtask[]; // Recursive field
}

import api from './api';
import { Subtask, SubtaskCreate } from '../types/subtask'; // Import for local use
export type { Subtask, SubtaskCreate } from '../types/subtask'; // Re-export as types

export const getSubtasks = async (taskId: string | number, parentSubtaskId?: number): Promise<Subtask[]> => {
    // Modify this to fetch based on parent_task_id OR parent_subtask_id
    let url = `/tasks/${taskId}/subtasks/`;
    if (parentSubtaskId) {
        url += `?parent_subtask_id=${parentSubtaskId}`;
    }
    const response = await api.get<Subtask[]>(url);
    return response.data;
};

export const createSubtask = async (
    parentTaskId: number | undefined, 
    parentSubtaskId: number | undefined, 
    subtaskData: SubtaskCreate
): Promise<Subtask> => {
    // Backend requires SubtaskCreate schema: name (mapped from title), owner_id
    const payload: any = {
        name: subtaskData.name,
        description: subtaskData.description,
        owner_id: subtaskData.owner_id,
        start_date: subtaskData.start_date,
        end_date: subtaskData.end_date,
        status: subtaskData.status,
        progress: subtaskData.progress,
        tag_ids: subtaskData.tag_ids,
        topic_ids: subtaskData.topic_ids,
    };

    let url = '';
    if (parentTaskId) {
        url = `/tasks/${parentTaskId}/subtasks/`;
        // Pass parent_subtask_id as query param if it exists
        if (parentSubtaskId) {
            url += `?parent_subtask_id=${parentSubtaskId}`;
        }
    } else if (parentSubtaskId) {
        // This case would mean creating a subtask directly under a subtask,
        // but the current backend router still links to a task.
        // The backend `create_subtask_for_task` needs a task_id path param.
        // We will assume that if parentSubtaskId is given, its parent task ID will be passed as taskId.
        // This logic needs to be refined if the backend ever supports direct subtask creation endpoints.
        // For now, if creating a sub-subtask, we always need the grand-parent task_id.
        // The backend `create_subtask_for_task` can handle parent_subtask_id in query.
        throw new Error("Cannot create subtask directly under another subtask without parent task ID. Use grand-parent task ID.");
    } else {
        throw new Error("Must provide either parentTaskId or parentSubtaskId.");
    }
    
    // Explicitly set parent_task_id/parent_subtask_id in payload if not already set by query param
    // This is for the backend Pydantic model
    if (parentTaskId) payload.parent_task_id = parentTaskId;
    if (parentSubtaskId) payload.parent_subtask_id = parentSubtaskId;


    const response = await api.post<Subtask>(url, payload);
    return response.data;
};

export const updateSubtask = async (subtaskId: string | number, updates: Partial<Subtask>): Promise<Subtask> => {
    const response = await api.put(`/subtasks/${subtaskId}`, updates);
    return response.data;
};

export const deleteSubtask = async (subtaskId: string | number): Promise<void> => {
    await api.delete(`/subtasks/${subtaskId}`);
};

import React, { useState } from 'react';
import { 
    Dialog, DialogTitle, DialogContent, DialogActions, Button, 
    FormControl, InputLabel, Select, MenuItem, CircularProgress, 
    Typography, Alert, SelectChangeEvent
} from '@mui/material';
import { getTasks } from '../../services/tasks';
import { createDependency } from '../../services/dependencyService';
import { Task } from '../../types/task';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

interface AddDependencyDialogProps {
    open: boolean;
    onClose: () => void;
    projectId: number;
    dependentTaskId: number; // The task that depends on something
}

const AddDependencyDialog: React.FC<AddDependencyDialogProps> = ({ open, onClose, projectId, dependentTaskId }) => {
    const [prerequisiteId, setPrerequisiteId] = useState<string>('');
    const [error, setError] = useState<string | null>(null);
    const queryClient = useQueryClient();

    // Fetch potential prerequisites (all tasks in project)
    const { data: tasks, isLoading } = useQuery({
        queryKey: ['projectTasks', projectId],
        queryFn: () => getTasks(projectId),
        enabled: open, // Only fetch when dialog is open
    });

    const createMutation = useMutation({
        mutationFn: createDependency,
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['taskDependencies', dependentTaskId] });
            onClose();
        },
        onError: () => {
            setError("Failed to create dependency. Check for circular dependencies.");
        }
    });

    const handleSubmit = () => {
        if (!prerequisiteId) return;
        setError(null);
        createMutation.mutate({
            dependent_id: dependentTaskId,
            prerequisite_id: Number(prerequisiteId)
        });
    };

    const handleChange = (event: SelectChangeEvent) => {
        setPrerequisiteId(event.target.value as string);
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle>Add Dependency</DialogTitle>
            <DialogContent>
                <Typography variant="body2" sx={{ mb: 2 }}>
                    Select a task that must be completed <b>before</b> the current task can start.
                </Typography>

                {isLoading ? (
                    <CircularProgress />
                ) : (
                    <FormControl fullWidth>
                        <InputLabel id="prerequisite-select-label">Prerequisite Task</InputLabel>
                        <Select
                            labelId="prerequisite-select-label"
                            value={prerequisiteId}
                            label="Prerequisite Task"
                            onChange={handleChange}
                        >
                            {tasks?.filter(t => t.id !== dependentTaskId).map((task) => (
                                <MenuItem key={task.id} value={task.id}>
                                    {task.name} (ID: {task.id})
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                )}

                {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose}>Cancel</Button>
                <Button onClick={handleSubmit} variant="contained" disabled={!prerequisiteId || createMutation.isPending}>
                    {createMutation.isPending ? 'Adding...' : 'Add Dependency'}
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default AddDependencyDialog;

import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    List,
    ListItem,
    ListItemText,
    ListItemSecondaryAction,
    IconButton,
    FormControl,
    InputLabel,
    Select,
    OutlinedInput,
    Chip,
    CircularProgress,
    Autocomplete,
    Slider
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import { createTask } from '../../services/tasks';
import { createSubtask } from '../../services/subtasks';
import { getUsers } from '../../services/users';
import { useAuth } from '../../context/AuthContext';
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { Tag } from '../../types/tag';
import { Topic } from '../../types/topic';
import { useQuery } from '@tanstack/react-query';


interface CreateTaskModalProps {
    open: boolean;
    onClose: () => void;
    projectId: string | number;
    onTaskCreated: () => void;
}

interface PendingSubtask {
    id?: number; // Will be set after creation, for now it's just pending
    name: string;
    description?: string;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    status: string;
    progress: number;
    tag_ids: number[];
    topic_ids: number[];
    parent_subtask_id?: number; // For nested subtasks
    parent_task_id?: number; // Added to track the grand-parent task
    nested_subtasks: PendingSubtask[];
}

const CreateTaskModal: React.FC<CreateTaskModalProps> = ({ open, onClose, projectId, onTaskCreated }) => {
    // Task State
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [promoterId, setPromoterId] = useState<number | null>(null); // Changed to null
    const [assigneeIds, setAssigneeIds] = useState<number[]>([]);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);

    // Data
    const [users, setUsers] = useState<any[]>([]);

    // Subtask State
    const [pendingSubtasks, setPendingSubtasks] = useState<PendingSubtask[]>([]);
    const [newSubtaskName, setNewSubtaskName] = useState('');
    const [newSubtaskDescription, setNewSubtaskDescription] = useState('');
    const [newSubtaskOwnerId, setNewSubtaskOwnerId] = useState<number | ''>('');
    const [newSubtaskStart, setNewSubtaskStart] = useState('');
    const [newSubtaskEnd, setNewSubtaskEnd] = useState('');
    const [newSubtaskProgress, setNewSubtaskProgress] = useState<number>(0);
    const [newSubtaskStatus, setNewSubtaskStatus] = useState('Not Started');
    const [newSubtaskTags, setNewSubtaskTags] = useState<Tag[]>([]);
    const [newSubtaskTopics, setNewSubtaskTopics] = useState<Topic[]>([]);
    const [newSubtaskParentSubtaskId, setNewSubtaskParentSubtaskId] = useState<number | ''>(''); // For nested subtasks
    const [isAddingSubtask, setIsAddingSubtask] = useState(false);

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const { user } = useAuth();

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]>({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });


    useEffect(() => {
        if (open) {
            fetchUsers();
        } else {
            resetForm();
        }
    }, [open]);

    const fetchUsers = async () => {
        try {
            const data = await getUsers();
            setUsers(data);
        } catch (err) {
            console.error("Failed to fetch users", err);
        }
    };

    const resetForm = () => {
        setName('');
        setDescription('');
        setStartDate('');
        setEndDate('');
        setStatus('Not Started');
        setPromoterId(null);
        setAssigneeIds([]);
        setPendingSubtasks([]);
        setNewSubtaskName('');
        setNewSubtaskDescription('');
        setNewSubtaskOwnerId('');
        setNewSubtaskStart('');
        setNewSubtaskEnd('');
        setNewSubtaskProgress(0);
        setNewSubtaskStatus('Not Started');
        setNewSubtaskTags([]);
        setNewSubtaskTopics([]);
        setNewSubtaskParentSubtaskId('');
        setIsAddingSubtask(false);
        setSelectedTags([]);
        setSelectedTopics([]);
        setError('');
    };

    const handleAddSubtask = () => {
        if (!newSubtaskName.trim()) {
            setError('Subtask name cannot be empty.');
            return;
        }
        if (!newSubtaskOwnerId) {
            setError('Subtask owner is required.');
            return;
        }
        if (!user || !user.id) {
            setError('You must be logged in to create a subtask.'); 
            return;
        }
        
        const newSubtask: PendingSubtask = {
            id: Date.now(), // Assign a temporary unique ID for managing in UI before actual creation
            name: newSubtaskName,
            description: newSubtaskDescription || undefined,
            owner_id: Number(newSubtaskOwnerId),
            start_date: newSubtaskStart || undefined,
            end_date: newSubtaskEnd || undefined,
            status: newSubtaskStatus,
            progress: newSubtaskProgress,
            tag_ids: newSubtaskTags.map(t => t.id),
            topic_ids: newSubtaskTopics.map(t => t.id),
            nested_subtasks: [] 
        };

        const addNestedSubtask = (
            subs: PendingSubtask[], 
            subToAdd: PendingSubtask, 
            targetParentTempId?: number
        ): PendingSubtask[] => {
            if (!targetParentTempId) {
                return [...subs, subToAdd];
            }

            return subs.map(s => {
                if (s.id === targetParentTempId) {
                    return {
                        ...s,
                        nested_subtasks: [...s.nested_subtasks, subToAdd]
                    };
                }
                return {
                    ...s,
                    nested_subtasks: addNestedSubtask(s.nested_subtasks, subToAdd, targetParentTempId)
                };
            });
        };

        setPendingSubtasks(prev => 
            addNestedSubtask(prev, newSubtask, newSubtaskParentSubtaskId !== '' ? Number(newSubtaskParentSubtaskId) : undefined)
        );

        setNewSubtaskName('');
        setNewSubtaskDescription('');
        setNewSubtaskOwnerId('');
        setNewSubtaskStart('');
        setNewSubtaskEnd('');
        setNewSubtaskProgress(0);
        setNewSubtaskStatus('Not Started');
        setNewSubtaskTags([]);
        setNewSubtaskTopics([]);
        setNewSubtaskParentSubtaskId('');
        setIsAddingSubtask(false);
        setError('');
    };

    const handleDeletePendingSubtask = (index: number) => {
        const updated = [...pendingSubtasks];
        updated.splice(index, 1);
        setPendingSubtasks(updated);
    };

    const createSubtasksRecursive = async (originalTaskId: number, currentParentId: number, subs: PendingSubtask[], isCurrentParentTask: boolean) => {
        for (const sub of subs) {
            let createdSubtask;
            const subtaskDataPayload = {
                name: sub.name,
                description: sub.description,
                owner_id: sub.owner_id,
                start_date: sub.start_date ? new Date(sub.start_date).toISOString() : undefined,
                end_date: sub.end_date ? new Date(sub.end_date).toISOString() : undefined,
                status: sub.status,
                progress: sub.progress,
                tag_ids: sub.tag_ids,
                topic_ids: sub.topic_ids,
            };

            if (isCurrentParentTask) { // Parent is a Task (currentParentId is the taskId)
                createdSubtask = await createSubtask(currentParentId, undefined, subtaskDataPayload);
            } else { // Parent is a Subtask (currentParentId is the parent_subtask_id)
                // When creating a sub-subtask, its immediate parent_task_id is the originalTaskId
                createdSubtask = await createSubtask(originalTaskId, currentParentId, subtaskDataPayload);
            }

            if (createdSubtask && sub.nested_subtasks.length > 0) {
                await createSubtasksRecursive(originalTaskId, createdSubtask.id, sub.nested_subtasks, false);
            }
        }
    };

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Task name is required');
            return;
        }

        if (!user || !user.id) {
            setError('You must be logged in to create a task');
            return;
        }

        setLoading(true);
        setError('');

        try {
            // 1. Create the Task
            const newTask = await createTask(projectId, {
                name,
                description,
                project_id: Number(projectId),
                owner_id: user.id,
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                promoter_id: promoterId,
                assignee_ids: assigneeIds,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
            });

            // 2. Create Subtasks if any
            if (pendingSubtasks.length > 0 && newTask.id) {
                await createSubtasksRecursive(newTask.id, newTask.id, pendingSubtasks, true);
            }

            onTaskCreated();
            onClose(); // resetForm called via useEffect dependency on open
        } catch (err) {
            console.error(err);
            setError('Failed to create task (or subtasks)');
        } finally {
            setLoading(false);
        }
    };

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];
    const formLoading = loading || isLoadingTags || isLoadingTopics;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Create New Task</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                {formLoading && <CircularProgress size={20} sx={{ mr: 1 }} />}

                <Grid container spacing={3}>
                    {/* Left Column: Task Details */}
                    <Grid item xs={12} md={6}>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                            <Typography variant="h6" sx={{ mb: 1 }}>Details</Typography>
                            <TextField
                                autoFocus
                                label="Task Name"
                                fullWidth
                                variant="outlined"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                disabled={formLoading}
                                required
                            />
                            <TextField
                                label="Description"
                                fullWidth
                                multiline
                                rows={3}
                                variant="outlined"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                disabled={formLoading}
                            />

                            <Grid container spacing={2}>
                                <Grid item xs={6}>
                                    <TextField
                                        label="Start Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        disabled={formLoading}
                                    />
                                </Grid>
                                <Grid item xs={6}>
                                    <TextField
                                        label="Due Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={endDate}
                                        onChange={(e) => setEndDate(e.target.value)}
                                        disabled={formLoading}
                                    />
                                </Grid>
                            </Grid>

                            <TextField
                                select
                                label="Status"
                                fullWidth
                                value={status}
                                onChange={(e) => setStatus(e.target.value)}
                                disabled={formLoading}
                            >
                                {statuses.map((option) => (
                                    <MenuItem key={option} value={option}>
                                        {option}
                                    </MenuItem>
                                ))}
                            </TextField>

                            <Autocomplete
                                id="promoter-select"
                                options={users}
                                getOptionLabel={(option) => option.email}
                                value={users.find(u => u.id === promoterId) || null}
                                onChange={(_, newValue) => setPromoterId(newValue ? newValue.id : null)}
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Promoter / Lead"
                                        placeholder="Select promoter"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <FormControl fullWidth>
                                <InputLabel id="assignees-label">Assignees (Team)</InputLabel>
                                <Select
                                    labelId="assignees-label"
                                    multiple
                                    value={assigneeIds}
                                    onChange={(e) => setAssigneeIds(typeof e.target.value === 'string' ? e.target.value.split(',').map(Number) : e.target.value as number[])}
                                    input={<OutlinedInput id="select-multiple-chip" label="Assignees (Team)" />}
                                    renderValue={(selected) => (
                                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                            {selected.map((value) => {
                                                const u = users.find(user => user.id === value);
                                                return <Chip key={value} label={u ? u.email : value} size="small" />;
                                            })}
                                        </Box>
                                    )}
                                >
                                    {users.map((u) => (
                                        <MenuItem key={u.id} value={u.id}>
                                            {u.email}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            <Autocomplete
                                multiple
                                id="task-tags-select"
                                options={availableTags || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTags}
                                onChange={(_, newValue) => setSelectedTags(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Tags"
                                        placeholder="Select tags"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <Autocomplete
                                multiple
                                id="task-topics-select"
                                options={availableTopics || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTopics}
                                onChange={(_, newValue) => setSelectedTopics(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Topics"
                                        placeholder="Select topics"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />
                        </Box>
                    </Grid>

                    {/* Right Column: Subtasks */}
                    <Grid item xs={12} md={6}>
                        <Typography variant="h6" sx={{ mb: 2 }}>Subtasks</Typography>
                        <Box sx={{ mb: 2 }}>
                            {isAddingSubtask ? (
                                <Box sx={{ p: 2, border: '1px solid #ddd', borderRadius: 2 }}>
                                    <TextField
                                        label="Subtask Name"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskName}
                                        onChange={(e) => setNewSubtaskName(e.target.value)}
                                        required
                                    />
                                    <TextField
                                        label="Description"
                                        size="small"
                                        fullWidth
                                        multiline
                                        rows={2}
                                        sx={{ mb: 2 }}
                                        value={newSubtaskDescription}
                                        onChange={(e) => setNewSubtaskDescription(e.target.value)}
                                    />
                                    <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                                        <InputLabel>Owner</InputLabel>
                                        <Select
                                            value={newSubtaskOwnerId}
                                            label="Owner"
                                            onChange={(e) => setNewSubtaskOwnerId(Number(e.target.value))}
                                            required
                                        >
                                            <MenuItem value=""><em>None</em></MenuItem>
                                            {users.map((u) => (
                                                <MenuItem key={u.id} value={u.id}>{u.email}</MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                    <TextField
                                        select
                                        label="Status"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskStatus}
                                        onChange={(e) => setNewSubtaskStatus(e.target.value)}
                                    >
                                        {statuses.map((option) => (
                                            <MenuItem key={option} value={option}>
                                                {option}
                                            </MenuItem>
                                        ))}
                                    </TextField>
                                    <Box sx={{ mb: 2 }}>
                                        <Typography variant="caption" gutterBottom>Progress: {newSubtaskProgress}%</Typography>
                                        <Slider
                                            value={newSubtaskProgress}
                                            onChange={(_, val) => setNewSubtaskProgress(val as number)}
                                            min={0}
                                            max={100}
                                            step={1}
                                            valueLabelDisplay="auto"
                                        />
                                    </Box>
                                    <Grid container spacing={1} sx={{ mb: 2 }}>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="Start"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskStart}
                                                onChange={(e) => setNewSubtaskStart(e.target.value)}
                                            />
                                        </Grid>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="End"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskEnd}
                                                onChange={(e) => setNewSubtaskEnd(e.target.value)}
                                            />
                                        </Grid>
                                    </Grid>
                                     <Autocomplete
                                        multiple
                                        id="subtask-tags-select"
                                        options={availableTags || []}
                                        getOptionLabel={(option) => option.name}
                                        value={newSubtaskTags}
                                        onChange={(_, newValue) => setNewSubtaskTags(newValue)}
                                        renderTags={(value, getTagProps) =>
                                            value.map((option, index) => (
                                                <Chip
                                                    variant="outlined"
                                                    label={option.name}
                                                    sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                                    {...getTagProps({ index })}
                                                    key={option.id}
                                                />
                                            ))
                                        }
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                variant="outlined"
                                                label="Tags"
                                                placeholder="Select tags"
                                                size="small"
                                                sx={{ mb: 2 }}
                                            />
                                        )}
                                    />
                                    <Autocomplete
                                        multiple
                                        id="subtask-topics-select"
                                        options={availableTopics || []}
                                        getOptionLabel={(option) => option.name}
                                        value={newSubtaskTopics}
                                        onChange={(_, newValue) => setNewSubtaskTopics(newValue)}
                                        renderTags={(value, getTagProps) =>
                                            value.map((option, index) => (
                                                <Chip
                                                    variant="outlined"
                                                    label={option.name}
                                                    {...getTagProps({ index })}
                                                    key={option.id}
                                                />
                                            ))
                                        }
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                variant="outlined"
                                                label="Topics"
                                                placeholder="Select topics"
                                                size="small"
                                                sx={{ mb: 2 }}
                                            />
                                        )}
                                    />
                                    <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                                        <InputLabel>Parent Subtask (optional)</InputLabel>
                                        <Select
                                            value={newSubtaskParentSubtaskId}
                                            label="Parent Subtask (optional)"
                                            onChange={(e) => setNewSubtaskParentSubtaskId(Number(e.target.value))}
                                        >
                                            <MenuItem value=""><em>None</em></MenuItem>
                                            {pendingSubtasks.map((sub, index) => (
                                                <MenuItem key={index} value={index}>{sub.name}</MenuItem> // Using index as value for pending subtasks
                                            ))}
                                        </Select>
                                    </FormControl>
                                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                                        <Button size="small" onClick={() => setIsAddingSubtask(false)}>Cancel</Button>
                                        <Button size="small" variant="contained" onClick={handleAddSubtask}>Add</Button>
                                    </Box>
                                </Box>
                            ) : (
                                <Button startIcon={<AddIcon />} fullWidth variant="outlined" onClick={() => setIsAddingSubtask(true)}>
                                    Add Subtask
                                </Button>
                            )}
                        </Box>

                        <List dense sx={{ bgcolor: 'background.paper', borderRadius: 1 }}>
                            {pendingSubtasks.map((sub, index) => (
                                <ListItem key={index} divider>
                                    <ListItemText
                                        primary={sub.name}
                                        secondary={
                                            sub.start_date || sub.end_date
                                                ? `${sub.start_date || '?'} - ${sub.end_date || '?'}`
                                                : "No dates set"
                                        }
                                    />
                                    <ListItemSecondaryAction>
                                        <IconButton edge="end" size="small" onClick={() => handleDeletePendingSubtask(index)}>
                                            <DeleteIcon fontSize="small" />
                                        </IconButton>
                                    </ListItemSecondaryAction>
                                </ListItem>
                            ))}
                            {pendingSubtasks.length === 0 && <Typography variant="body2" color="text.secondary" align="center">No subtasks added yet.</Typography>}
                        </List>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={formLoading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={formLoading}
                    sx={{ px: 4 }}
                >
                    Create Task
                </Button>
            </DialogActions>
        </Dialog>
    );
};

