import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    IconButton,
    List,
    ListItem,
    ListItemText,
    ListItemSecondaryAction,
    Select,
    InputLabel,
    FormControl,
    OutlinedInput,
    Chip,
    Slider, // Import Slider
    Autocomplete,
    CircularProgress
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import SyncIcon from '@mui/icons-material/Sync';
import EditIcon from '@mui/icons-material/Edit'; // Import EditIcon
import SubtaskHierarchyRenderer from './SubtaskHierarchyRenderer'; // Import SubtaskHierarchyRenderer
import SubtaskEditor from './SubtaskEditor'; // Import SubtaskEditor
import { updateTask } from '../../services/tasks';
import { getSubtasks, createSubtask, deleteSubtask, updateSubtask, Subtask } from '../../services/subtasks';
import { getUsers } from '../../services/users';
import { useAuth } from '../../context/AuthContext';
import { format, isValid, parseISO, min, max } from 'date-fns';
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { Tag } from '../../types/tag';
import { Topic } from '../../types/topic';
import { useQuery } from '@tanstack/react-query';


interface EditTaskModalProps {
    open: boolean;
    onClose: () => void;
    task: any;
    onTaskUpdated: () => void;
}

const EditTaskModal: React.FC<EditTaskModalProps> = ({ open, onClose, task, onTaskUpdated }) => {
    // Task State
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [promoterId, setPromoterId] = useState<number | null>(null); // Changed to null
    const [assigneeIds, setAssigneeIds] = useState<number[]>([]);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);
    
    // Data
    const [users, setUsers] = useState<any[]>([]);

    // Subtask State
    const [subtasks, setSubtasks] = useState<Subtask[]>([]);
    const [newSubtaskName, setNewSubtaskName] = useState('');
    const [newSubtaskDescription, setNewSubtaskDescription] = useState('');
    const [newSubtaskOwnerId, setNewSubtaskOwnerId] = useState<number | ''>('');
    const [newSubtaskStart, setNewSubtaskStart] = useState('');
    const [newSubtaskEnd, setNewSubtaskEnd] = useState('');
    const [newSubtaskProgress, setNewSubtaskProgress] = useState<number>(0);
    const [newSubtaskStatus, setNewSubtaskStatus] = useState('Not Started');
    const [newSubtaskTags, setNewSubtaskTags] = useState<Tag[]>([]);
    const [newSubtaskTopics, setNewSubtaskTopics] = useState<Topic[]>([]);
    const [newSubtaskParentSubtaskId, setNewSubtaskParentSubtaskId] = useState<number | ''>(''); // For nested subtasks
    const [isAddingSubtask, setIsAddingSubtask] = useState(false);
    const [editingSubtask, setEditingSubtask] = useState<Subtask | null>(null); // State for editing existing subtask

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const { user } = useAuth();

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]>({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });

    useEffect(() => {
        if (open) {
            fetchUsers();
        }
    }, [open]);

    useEffect(() => {
        if (task && open) {
            setName(task.name || '');
            setDescription(task.description || '');
            setStartDate(task.start_date ? task.start_date.split('T')[0] : '');
            setEndDate(task.end_date ? task.end_date.split('T')[0] : '');
            setStatus(task.status || 'Not Started');
            setPromoterId(task.promoter_id || null); // Initialize with null
            setAssigneeIds(task.assignees ? task.assignees.map((u: any) => u.id) : []);
            setSelectedTags(task.tags || []);
            setSelectedTopics(task.topics || []);
            fetchSubtasks();
        }
    }, [task, open]);

    const fetchUsers = async () => {
        try {
            const data = await getUsers();
            setUsers(data);
        } catch (err) {
            console.error("Failed to fetch users", err);
        }
    };

    const fetchSubtasks = async () => {
        try {
            if (task?.id) {
                const data = await getSubtasks(task.id);
                setSubtasks(data);
            }
        } catch (err) {
            console.error("Failed to load subtasks", err);
        }
    };

    // Calculate Min/Max from Subtasks
    const getSuggestedDates = () => {
        if (subtasks.length === 0) return null;

        const validStartDates = subtasks
            .map(s => s.start_date ? parseISO(s.start_date) : null)
            .filter((d): d is Date => isValid(d));

        const validEndDates = subtasks
            .map(s => s.end_date ? parseISO(s.end_date) : null)
            .filter((d): d is Date => isValid(d));

        if (validStartDates.length === 0 && validEndDates.length === 0) return null;

        const minStart = validStartDates.length > 0 ? min(validStartDates) : null;
        const maxEnd = validEndDates.length > 0 ? max(validEndDates) : null;

        return {
            start: minStart ? format(minStart, 'yyyy-MM-dd') : '',
            end: maxEnd ? format(maxEnd, 'yyyy-MM-dd') : ''
        };
    };

    const handleSyncDates = () => {
        const suggestions = getSuggestedDates();
        if (suggestions) {
            if (suggestions.start) setStartDate(suggestions.start);
            if (suggestions.end) setEndDate(suggestions.end);
        }
    };

    const handleAddSubtask = async () => {
        if (!newSubtaskName.trim()) {
            setError('Subtask name cannot be empty.');
            return;
        }
        if (!newSubtaskOwnerId) {
            setError('Subtask owner is required.');
            return;
        }
        if (!user || !user.id) {
            setError('You must be logged in to create a subtask.');
            return;
        }
        
        try {
            await createSubtask(
                task.id, // Parent task ID
                newSubtaskParentSubtaskId === '' ? undefined : Number(newSubtaskParentSubtaskId), // Parent subtask ID
                {
                    name: newSubtaskName,
                    description: newSubtaskDescription || undefined,
                    owner_id: Number(newSubtaskOwnerId),
                    start_date: newSubtaskStart ? new Date(newSubtaskStart).toISOString() : undefined,
                    end_date: newSubtaskEnd ? new Date(newSubtaskEnd).toISOString() : undefined,
                    status: newSubtaskStatus,
                    progress: newSubtaskProgress,
                    tag_ids: newSubtaskTags.map(t => t.id),
                    topic_ids: newSubtaskTopics.map(t => t.id),
                }
            );
            setNewSubtaskName('');
            setNewSubtaskDescription('');
            setNewSubtaskOwnerId('');
            setNewSubtaskStart('');
            setNewSubtaskEnd('');
            setNewSubtaskProgress(0);
            setNewSubtaskStatus('Not Started');
            setNewSubtaskTags([]);
            setNewSubtaskTopics([]);
            setNewSubtaskParentSubtaskId('');
            setIsAddingSubtask(false);
            fetchSubtasks();
        } catch (err) {
            console.error(err);
            setError("Failed to add subtask");
        }
    };

    const handleDeleteSubtask = async (id: string | number) => {
        if (!window.confirm("Delete subtask?")) return;
        try {
            await deleteSubtask(id);
            fetchSubtasks();
        } catch (err) {
            console.error(err);
        }
    };

    const handleToggleSubtask = async (sub: Subtask) => {
        try {
            const newStatus = sub.status === 'Completed' ? 'Not Started' : 'Completed';
            await updateSubtask(sub.id, { status: newStatus });
            // Optimistic update or refetch
            setSubtasks(prev => prev.map(s => s.id === sub.id ? { ...s, status: newStatus } : s));
        } catch (err) {
            console.error("Failed to update subtask status", err);
            setError("Failed to update subtask status");
        }
    };

    const handleEditSubtask = (subtaskToEdit: Subtask) => {
        setEditingSubtask(subtaskToEdit);
    };

    const handleSubtaskUpdated = () => {
        fetchSubtasks(); // Refetch subtasks to get latest data
        setEditingSubtask(null); // Close editor
    };

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Task name is required');
            return;
        }

        setLoading(true);
        setError('');

        try {
            await updateTask(task.id, {
                name,
                description,
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                promoter_id: promoterId,
                assignee_ids: assigneeIds,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
            });
            onTaskUpdated();
            onClose();
        } catch (err) {
            console.error(err);
            setError('Failed to update task');
        } finally {
            setLoading(false);
        }
    };

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];
    const suggestions = getSuggestedDates();
    const formLoading = loading || isLoadingTags || isLoadingTopics;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Edit Task</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

                <Grid container spacing={3}>
                    {/* Left Column: Task Details */}
                    <Grid item xs={12} md={6}>
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                            {/* ... (Previous Fields) ... */}
                            <Typography variant="h6" sx={{ mb: 1 }}>Details</Typography>
                            <TextField
                                label="Task Name"
                                fullWidth
                                variant="outlined"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                disabled={loading}
                                required
                            />
                            <TextField
                                label="Description"
                                fullWidth
                                multiline
                                rows={3}
                                variant="outlined"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                disabled={loading}
                            />

                            <Grid container spacing={2} alignItems="center">
                                <Grid item xs={6}>
                                    <TextField
                                        label="Start Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={startDate}
                                        onChange={(e) => setStartDate(e.target.value)}
                                        disabled={loading}
                                    />
                                </Grid>
                                <Grid item xs={6}>
                                    <TextField
                                        label="Due Date"
                                        type="date"
                                        fullWidth
                                        InputLabelProps={{ shrink: true }}
                                        value={endDate}
                                        onChange={(e) => setEndDate(e.target.value)}
                                        disabled={loading}
                                    />
                                </Grid>
                            </Grid>

                            {suggestions && (suggestions.start || suggestions.end) && (
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, bgcolor: 'action.hover', p: 1, borderRadius: 1 }}>
                                    <SyncIcon color="primary" fontSize="small" />
                                    <Typography variant="caption" color="text.secondary">
                                        Suggested: {suggestions.start || '...'} to {suggestions.end || '...'}
                                    </Typography>
                                    <Button size="small" onClick={handleSyncDates}>Apply</Button>
                                </Box>
                            )}

                            <TextField
                                select
                                label="Status"
                                fullWidth
                                value={status}
                                onChange={(e) => setStatus(e.target.value)}
                                disabled={loading}
                            >
                                {statuses.map((option) => (
                                    <MenuItem key={option} value={option}>
                                        {option}
                                    </MenuItem>
                                ))}
                            </TextField>

                            <Autocomplete
                                id="promoter-select"
                                options={users}
                                getOptionLabel={(option) => option.email}
                                value={users.find(u => u.id === promoterId) || null}
                                onChange={(_, newValue) => setPromoterId(newValue ? newValue.id : null)}
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Promoter / Lead"
                                        placeholder="Select promoter"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <FormControl fullWidth>
                                <InputLabel id="assignees-label">Assignees (Team)</InputLabel>
                                <Select
                                    labelId="assignees-label"
                                    multiple
                                    value={assigneeIds}
                                    onChange={(e) => setAssigneeIds(typeof e.target.value === 'string' ? e.target.value.split(',').map(Number) : e.target.value as number[])}
                                    input={<OutlinedInput id="select-multiple-chip" label="Assignees (Team)" />}
                                    renderValue={(selected) => (
                                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                            {selected.map((value) => {
                                                const u = users.find(user => user.id === value);
                                                return <Chip key={value} label={u ? u.email : value} size="small" />;
                                            })}
                                        </Box>
                                    )}
                                >
                                    {users.map((u) => (
                                        <MenuItem key={u.id} value={u.id}>
                                            {u.email}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>

                            <Autocomplete
                                multiple
                                id="task-tags-select"
                                options={availableTags || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTags}
                                onChange={(_, newValue) => setSelectedTags(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Tags"
                                        placeholder="Select tags"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />

                            <Autocomplete
                                multiple
                                id="task-topics-select"
                                options={availableTopics || []}
                                getOptionLabel={(option) => option.name}
                                value={selectedTopics}
                                onChange={(_, newValue) => setSelectedTopics(newValue)}
                                renderTags={(value, getTagProps) =>
                                    value.map((option, index) => (
                                        <Chip
                                            variant="outlined"
                                            label={option.name}
                                            {...getTagProps({ index })}
                                            key={option.id}
                                        />
                                    ))
                                }
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Topics"
                                        placeholder="Select topics"
                                        disabled={formLoading}
                                    />
                                )}
                                sx={{ mt: 2 }}
                            />
                        </Box>
                    </Grid>

                    {/* Right Column: Subtasks */}
                    <Grid item xs={12} md={6}>
                        {/* Subtasks UI */}
                        <Typography variant="h6" sx={{ mb: 2 }}>Subtasks</Typography>
                        <Box sx={{ mb: 2 }}>
                            {isAddingSubtask ? (
                                <Box sx={{ p: 2, border: '1px solid #ddd', borderRadius: 2 }}>
                                    <TextField
                                        label="Subtask Name"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskName}
                                        onChange={(e) => setNewSubtaskName(e.target.value)}
                                        required
                                    />
                                    <TextField
                                        label="Description"
                                        size="small"
                                        fullWidth
                                        multiline
                                        rows={2}
                                        sx={{ mb: 2 }}
                                        value={newSubtaskDescription}
                                        onChange={(e) => setNewSubtaskDescription(e.target.value)}
                                    />
                                    <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                                        <InputLabel>Owner</InputLabel>
                                        <Select
                                            value={newSubtaskOwnerId}
                                            label="Owner"
                                            onChange={(e) => setNewSubtaskOwnerId(Number(e.target.value))}
                                            required
                                        >
                                            <MenuItem value=""><em>None</em></MenuItem>
                                            {users.map((u) => (
                                                <MenuItem key={u.id} value={u.id}>{u.email}</MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                    <TextField
                                        select
                                        label="Status"
                                        size="small"
                                        fullWidth
                                        sx={{ mb: 2 }}
                                        value={newSubtaskStatus}
                                        onChange={(e) => setNewSubtaskStatus(e.target.value)}
                                    >
                                        {statuses.map((option) => (
                                            <MenuItem key={option} value={option}>
                                                {option}
                                            </MenuItem>
                                        ))}
                                    </TextField>
                                    <Box sx={{ mb: 2 }}>
                                        <Typography variant="caption" gutterBottom>Progress: {newSubtaskProgress}%</Typography>
                                        <Slider
                                            value={newSubtaskProgress}
                                            onChange={(_, val) => setNewSubtaskProgress(val as number)}
                                            min={0}
                                            max={100}
                                            step={1}
                                            valueLabelDisplay="auto"
                                        />
                                    </Box>
                                    <Grid container spacing={1} sx={{ mb: 2 }}>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="Start"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskStart}
                                                onChange={(e) => setNewSubtaskStart(e.target.value)}
                                            />
                                        </Grid>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="End"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskEnd}
                                                onChange={(e) => setNewSubtaskEnd(e.target.value)}
                                            />
                                        </Grid>
                                    </Grid>
                                     <Autocomplete
                                        multiple
                                        id="subtask-tags-select"
                                        options={availableTags || []}
                                        getOptionLabel={(option) => option.name}
                                        value={newSubtaskTags}
                                        onChange={(_, newValue) => setNewSubtaskTags(newValue)}
                                        renderTags={(value, getTagProps) =>
                                            value.map((option, index) => (
                                                <Chip
                                                    variant="outlined"
                                                    label={option.name}
                                                    sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                                    {...getTagProps({ index })}
                                                    key={option.id}
                                                />
                                            ))
                                        }
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                variant="outlined"
                                                label="Tags"
                                                placeholder="Select tags"
                                                size="small"
                                                sx={{ mb: 2 }}
                                            />
                                        )}
                                    />
                                    <Autocomplete
                                        multiple
                                        id="subtask-topics-select"
                                        options={availableTopics || []}
                                        getOptionLabel={(option) => option.name}
                                        value={newSubtaskTopics}
                                        onChange={(_, newValue) => setNewSubtaskTopics(newValue)}
                                        renderTags={(value, getTagProps) =>
                                            value.map((option, index) => (
                                                <Chip
                                                    variant="outlined"
                                                    label={option.name}
                                                    {...getTagProps({ index })}
                                                    key={option.id}
                                                />
                                            ))
                                        }
                                        renderInput={(params) => (
                                            <TextField
                                                {...params}
                                                variant="outlined"
                                                label="Topics"
                                                placeholder="Select topics"
                                                size="small"
                                                sx={{ mb: 2 }}
                                            />
                                        )}
                                    />
                                    <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                                        <InputLabel>Parent Subtask (optional)</InputLabel>
                                        <Select
                                            value={newSubtaskParentSubtaskId}
                                            label="Parent Subtask (optional)"
                                            onChange={(e) => setNewSubtaskParentSubtaskId(Number(e.target.value))}
                                        >
                                            <MenuItem value=""><em>None</em></MenuItem>
                                            {subtasks.map((sub) => (
                                                <MenuItem key={sub.id} value={sub.id}>{sub.name}</MenuItem>
                                            ))}
                                        </Select>
                                    </FormControl>
                                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                                        <Button size="small" onClick={() => setIsAddingSubtask(false)}>Cancel</Button>
                                        <Button size="small" variant="contained" onClick={handleAddSubtask}>Add</Button>
                                    </Box>
                                </Box>
                            ) : (
                                <Button startIcon={<AddIcon />} fullWidth variant="outlined" onClick={() => setIsAddingSubtask(true)}>
                                    Add Subtask
                                </Button>
                            )}
                        </Box>

                        <List dense sx={{ bgcolor: 'background.paper', borderRadius: 1 }}>
                            <SubtaskHierarchyRenderer
                                subtasks={subtasks}
                                onToggleSubtask={handleToggleSubtask}
                                onDeleteSubtask={handleDeleteSubtask}
                                onEditSubtask={handleEditSubtask}
                                users={users}
                            />
                            {subtasks.length === 0 && <Typography variant="body2" color="text.secondary" align="center">No subtasks yet.</Typography>}
                        </List>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
            {editingSubtask && (
                <SubtaskEditor
                    open={Boolean(editingSubtask)}
                    onClose={() => setEditingSubtask(null)}
                    subtask={editingSubtask}
                    onSubtaskUpdated={handleSubtaskUpdated}
                    users={users}
                />
            )}
        </Dialog>
    );
};

export default EditTaskModal;

import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    Select,
    InputLabel,
    FormControl,
    Slider,
    CircularProgress, // Import CircularProgress
    Autocomplete,     // Import Autocomplete
    Chip              // Import Chip
} from '@mui/material';
import { updateSubtask, Subtask } from '../../services/subtasks';
import { User } from '../../types/user'; // User interface moved to types/user
import { Tag } from '../../types/tag'; // Import Tag type
import { Topic } from '../../types/topic'; // Import Topic type
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { useQuery } from '@tanstack/react-query'; // Import useQuery

interface SubtaskEditorProps {
    open: boolean;
    onClose: () => void;
    subtask: Subtask;
    onSubtaskUpdated: () => void;
    users: User[]; // Pass users list for owner selection
    currentTaskSubtasks: Subtask[]; // Pass all subtasks of the current task for parent selection
}

const SubtaskEditor: React.FC<SubtaskEditorProps> = ({ open, onClose, subtask, onSubtaskUpdated, users, currentTaskSubtasks }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [ownerId, setOwnerId] = useState<number | ''>('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [progress, setProgress] = useState<number>(0);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);
    const [parentSubtaskId, setParentSubtaskId] = useState<number | undefined>(undefined);

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];

    // Helper to check if a subtask is a descendant of another
    const isDescendant = (potentialDescendant: Subtask, potentialAncestorId: number): boolean => {
        let current: Subtask | undefined = potentialDescendant;
        while (current) {
            if (current.parent_subtask_id === potentialAncestorId) {
                return true;
            }
            if (current.parent_subtask_id) {
                current = currentTaskSubtasks.find(s => s.id === current.parent_subtask_id);
            } else {
                current = undefined;
            }
        }
        return false;
    };

    const availableParentSubtasks = currentTaskSubtasks.filter(s =>
        s.id !== subtask.id && !isDescendant(s, subtask.id)
    );

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]>({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });

    const formLoading = loading || isLoadingTags || isLoadingTopics;

    useEffect(() => {
        if (subtask && open) {
            setName(subtask.name || '');
            setDescription(subtask.description || '');
            setOwnerId(subtask.owner_id || '');
            setStartDate(subtask.start_date ? subtask.start_date.split('T')[0] : '');
            setEndDate(subtask.end_date ? subtask.end_date.split('T')[0] : '');
            setStatus(subtask.status || 'Not Started');
            setProgress(subtask.progress || 0);
            setSelectedTags(subtask.tags || []);
            setSelectedTopics(subtask.topics || []);
            setParentSubtaskId(subtask.parent_subtask_id || undefined);
        }
    }, [subtask, open]);

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Subtask name is required');
            return;
        }

        setLoading(true);
        setError('');

        try {
            await updateSubtask(subtask.id, {
                name,
                description: description || undefined,
                owner_id: ownerId === '' ? undefined : Number(ownerId),
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                progress,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
                parent_subtask_id: parentSubtaskId,
                // Only set parent_task_id if parent_subtask_id is undefined, otherwise it should be derived from the parent subtask
                parent_task_id: parentSubtaskId === undefined ? subtask.parent_task_id : undefined 
            });
            onSubtaskUpdated();
            onClose();
        } catch (err) {
            console.error(err);
            setError('Failed to update subtask');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Edit Subtask: {subtask?.name}</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                {formLoading && <CircularProgress size={20} sx={{ mr: 1 }} />}
                <Box sx={{ mt: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <TextField
                        autoFocus
                        label="Subtask Name"
                        fullWidth
                        variant="outlined"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        disabled={loading}
                        required
                    />
                    <TextField
                        label="Description"
                        fullWidth
                        multiline
                        rows={2}
                        variant="outlined"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        disabled={loading}
                    />
                    <FormControl fullWidth>
                        <InputLabel>Owner</InputLabel>
                        <Select
                            value={ownerId}
                            label="Owner"
                            onChange={(e) => setOwnerId(Number(e.target.value))}
                            disabled={loading}
                        >
                            <MenuItem value=""><em>None</em></MenuItem>
                            {users.map((u) => (
                                <MenuItem key={u.id} value={u.id}>{u.email}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <TextField
                                label="Start Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={startDate}
                                onChange={(e) => setStartDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="End Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={endDate}
                                onChange={(e) => setEndDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                    </Grid>
                    <FormControl fullWidth>
                        <InputLabel>Status</InputLabel>
                        <Select
                            value={status}
                            label="Status"
                            onChange={(e) => setStatus(e.target.value)}
                            disabled={loading}
                        >
                            {statuses.map((option) => (
                                <MenuItem key={option} value={option}>
                                    {option}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Box>
                        <Typography variant="caption" gutterBottom>Progress: {progress}%</Typography>
                        <Slider
                            value={progress}
                            onChange={(_, val) => setProgress(val as number)}
                            aria-labelledby="progress-slider"
                            min={0}
                            max={100}
                            step={1}
                            valueLabelDisplay="auto"
                            disabled={loading}
                        />
                    </Box>

                    <Autocomplete
                        id="subtask-parent-select"
                        options={availableParentSubtasks}
                        getOptionLabel={(option) => option.name}
                        value={availableParentSubtasks.find(s => s.id === parentSubtaskId) || null}
                        onChange={(_, newValue) => setParentSubtaskId(newValue ? Number(newValue.id) : undefined)}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Parent Subtask (Optional)"
                                placeholder="Select parent subtask"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />

                    <Autocomplete
                        multiple
                        id="subtask-tags-select"
                        options={availableTags || []}
                        getOptionLabel={(option) => option.name}
                        value={selectedTags}
                        onChange={(_, newValue) => setSelectedTags(newValue)}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => (
                                <Chip
                                    variant="outlined"
                                    label={option.name}
                                    sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                    {...getTagProps({ index })}
                                    key={option.id}
                                />
                            ))
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Tags"
                                placeholder="Select tags"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />

                    <Autocomplete
                        multiple
                        id="subtask-topics-select"
                        options={availableTopics || []}
                        getOptionLabel={(option) => option.name}
                        value={selectedTopics}
                        onChange={(_, newValue) => setSelectedTopics(newValue)}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => (
                                <Chip
                                    variant="outlined"
                                    label={option.name}
                                    {...getTagProps({ index })}
                                    key={option.id}
                                />
                            ))
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Topics"
                                placeholder="Select topics"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />
                </Box>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default SubtaskEditor;

import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Typography,
    Box,
    Chip,
    Avatar,
    IconButton,
    TextField,
    useTheme,
    alpha,
    Grid,
    Checkbox,
    List,
    ListItem,
    ListItemIcon,
    ListItemText,
    ListItemSecondaryAction,
    CircularProgress,
    MenuItem,
    Select,
    FormControl
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import DeleteIcon from '@mui/icons-material/Delete';
import { Task } from '../../types/task';
import { createSubtask, getSubtasks, updateSubtask, deleteSubtask, Subtask } from '../../services/subtasks';
import { updateTask } from '../../services/tasks';
import { useAuth } from '../../context/AuthContext';

interface TaskDetailModalProps {
    open: boolean;
    onClose: () => void;
    task: Task | null;
    onTaskUpdated?: () => void;
}

const TaskDetailModal: React.FC<TaskDetailModalProps> = ({ open, onClose, task, onTaskUpdated }) => {
    const theme = useTheme();
    const { user } = useAuth();

    // Task Edit State
    const [description, setDescription] = useState('');
    const [priority, setPriority] = useState<string>('medium');
    const [dueDate, setDueDate] = useState<string>('');
    const [isSaving, setIsSaving] = useState(false);

    // Subtask State
    const [subtasks, setSubtasks] = useState<Subtask[]>([]);
    const [newSubtaskTitle, setNewSubtaskTitle] = useState('');
    const [isLoadingSubtasks, setIsLoadingSubtasks] = useState(false);
    const [isCreatingSubtask, setIsCreatingSubtask] = useState(false);

    useEffect(() => {
        if (task && open) {
            setDescription(task.description || '');
            setPriority(task.priority || 'medium');
            setDueDate(task.due_date ? task.due_date.split('T')[0] : ''); // Format YYYY-MM-DD for input
            fetchSubtasks();
        }
    }, [task, open]);

    const fetchSubtasks = async () => {
        if (!task) return;
        setIsLoadingSubtasks(true);
        try {
            const data = await getSubtasks(task.id);
            setSubtasks(data);
        } catch (error) {
            console.error("Failed to fetch subtasks", error);
        } finally {
            setIsLoadingSubtasks(false);
        }
    };

    const handleCreateSubtask = async () => {
        if (!newSubtaskTitle.trim() || !task || !user) return;
        setIsCreatingSubtask(true);
        try {
            // Pass undefined for parentSubtaskId as it's a top-level subtask for this task
            const created = await createSubtask(task.id, undefined, { name: newSubtaskTitle, owner_id: user.id });
            setSubtasks(prev => [...prev, created]);
            setNewSubtaskTitle('');
        } catch (error) {
            console.error("Failed to create subtask", error);
        } finally {
            setIsCreatingSubtask(false);
        }
    };

    const handleToggleSubtask = async (subtask: Subtask) => {
        try {
            // Check status and toggle
            // Backend schema uses 'status'
            const newStatus = subtask.status === 'Completed' ? 'Not Started' : 'Completed';
            await updateSubtask(subtask.id, { status: newStatus });

            setSubtasks(prev => prev.map(s => s.id === subtask.id ? { ...s, status: newStatus, is_completed: newStatus === 'Completed' } : s));
        } catch (error) {
            console.error("Failed to update subtask", error);
        }
    };

    const handleDeleteSubtask = async (subtaskId: string | number) => {
        try {
            await deleteSubtask(subtaskId);
            setSubtasks(prev => prev.filter(s => s.id !== subtaskId));
        } catch (error) {
            console.error("Failed to delete subtask", error);
        }
    };

    const handleSaveChanges = async () => {
        if (!task) return;
        setIsSaving(true);
        try {
            await updateTask(task.id, {
                description,
                priority,
                due_date: dueDate ? new Date(dueDate).toISOString() : undefined // Align with backend expectation if needed
            });
            if (onTaskUpdated) onTaskUpdated();
            onClose();
        } catch (error) {
            console.error("Failed to update task", error);
        } finally {
            setIsSaving(false);
        }
    };

    if (!task) return null;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: {
                    borderRadius: '16px',
                    bgcolor: alpha(theme.palette.background.paper, 0.95),
                    backdropFilter: 'blur(16px)',
                    backgroundImage: 'none'
                }
            }}
        >
            <DialogTitle sx={{ m: 0, p: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Typography variant="h6" fontWeight="700">
                        {task.name}
                    </Typography>
                    <Chip
                        label={task.status}
                        size="small"
                        sx={{ textTransform: 'capitalize', fontWeight: 600 }}
                    />
                </Box>
                <IconButton onClick={onClose}>
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent dividers sx={{ p: 4, border: 'none' }}>
                <Grid container spacing={4}>
                    <Grid item xs={12} md={8}>
                        <Box>
                            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                                Description
                            </Typography>
                            <TextField
                                fullWidth
                                multiline
                                rows={4}
                                placeholder="Add a more detailed description..."
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                variant="outlined"
                                sx={{ mb: 4 }}
                            />
                        </Box>

                        <Box>
                            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                                Subtasks
                            </Typography>
                            {isLoadingSubtasks ? (
                                <CircularProgress size={24} />
                            ) : (
                                <List dense>
                                    {subtasks.map(subtask => {
                                        const isCompleted = subtask.status === 'Completed' || subtask.is_completed;
                                        return (
                                            <ListItem key={subtask.id} disableGutters>
                                                <ListItemIcon sx={{ minWidth: 32 }}>
                                                    <Checkbox
                                                        edge="start"
                                                        checked={!!isCompleted}
                                                        tabIndex={-1}
                                                        disableRipple
                                                        onChange={() => handleToggleSubtask(subtask)}
                                                    />
                                                </ListItemIcon>
                                                <ListItemText
                                                    primary={subtask.name || subtask.title}
                                                    sx={{
                                                        textDecoration: isCompleted ? 'line-through' : 'none',
                                                        color: isCompleted ? 'text.secondary' : 'text.primary'
                                                    }}
                                                />
                                                <ListItemSecondaryAction>
                                                    <IconButton edge="end" aria-label="delete" size="small" onClick={() => handleDeleteSubtask(subtask.id)}>
                                                        <DeleteIcon fontSize="small" />
                                                    </IconButton>
                                                </ListItemSecondaryAction>
                                            </ListItem>
                                        );
                                    })}
                                </List>
                            )}
                            <Box sx={{ display: 'flex', gap: 1, mt: 2 }}>
                                <TextField
                                    fullWidth
                                    size="small"
                                    placeholder="Add a subtask..."
                                    value={newSubtaskTitle}
                                    onChange={(e) => setNewSubtaskTitle(e.target.value)}
                                    onKeyPress={(e) => e.key === 'Enter' && handleCreateSubtask()}
                                />
                                <Button
                                    variant="contained"
                                    onClick={handleCreateSubtask}
                                    disabled={!newSubtaskTitle.trim() || isCreatingSubtask}
                                    sx={{ minWidth: 80 }}
                                >
                                    Add
                                </Button>
                            </Box>
                        </Box>
                    </Grid>

                    <Grid item xs={12} md={4}>
                        <Box sx={{ p: 3, bgcolor: alpha(theme.palette.background.default, 0.5), borderRadius: '12px' }}>
                            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                                Custom Fields
                            </Typography>

                            <Box sx={{ mt: 2 }}>
                                <Typography variant="caption" color="text.secondary">Assignees</Typography>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                                    {task.assignees && task.assignees.length > 0 ? (
                                        task.assignees.map((assignee, index) => (
                                            <Avatar key={index} sx={{ width: 24, height: 24, fontSize: '0.75rem' }}>
                                                {assignee.email.charAt(0).toUpperCase()}
                                            </Avatar>
                                        ))
                                    ) : (
                                        <Avatar sx={{ width: 24, height: 24 }}>U</Avatar>
                                    )}
                                    <Typography variant="body2">
                                        {task.assignees && task.assignees.length > 0
                                            ? task.assignees.map(a => a.email).join(', ')
                                            : 'Unassigned'}
                                    </Typography>
                                </Box>
                            </Box>

                            <Box sx={{ mt: 3 }}>
