const isDescendant = (potentialDescendant: Subtask, potentialAncestorId: number): boolean => {
    let current: Subtask | undefined = potentialDescendant;
    while (current) {
        const parentId = current.parent_subtask_id;
        if (parentId === potentialAncestorId) {
            return true;
        }
        if (parentId) {
            current = currentTaskSubtasks.find(s => s.id === parentId);
        } else {
            current = undefined;
        }
    }
    return false;
};

