import React from 'react';
import {
    Box,
    Paper,
    Typography,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Chip,
    Button,
} from '@mui/material';
import { format, isValid } from 'date-fns';
import { useNavigate } from 'react-router-dom';
import ArrowForwardIcon from '@mui/icons-material/ArrowForward';

interface Task {
    id: number;
    name: string;
    status: string;
    end_date?: string;
    priority?: string;
    project_id: number;
    project_name?: string;
}

interface RecentTasksTableProps {
    tasks: Task[];
}

const safeFormat = (dateStr: string | undefined, fmt: string) => {
    if (!dateStr) return '-';
    const d = new Date(dateStr);
    return isValid(d) ? format(d, fmt) : '-';
};

const getStatusColor = (status: string) => {
    switch (status) {
        case 'Completed': return 'success';
        case 'In Progress': return 'primary';
        case 'Review': return 'warning';
        default: return 'default';
    }
};

/**
 * RecentTasksTable Component
 * 
 * Displays a table of the most recent tasks (limited to 5).
 * Columns: Name, Project, Status, Due Date, Action.
 * 
 * @param {Task[]} tasks - List of tasks to display.
 */
const RecentTasksTable: React.FC<RecentTasksTableProps> = ({ tasks }) => {
    const navigate = useNavigate();

    // Show only last 5 tasks
    const recentTasks = tasks.slice(0, 5);

    return (
        <Paper sx={{ p: 0, overflow: 'hidden' }}>
            <Box sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Typography variant="h6" fontWeight="600">
                    Recent Tasks
                </Typography>
                <Button 
                    endIcon={<ArrowForwardIcon />} 
                    size="small"
                    onClick={() => navigate('/projects')}
                >
                    View All
                </Button>
            </Box>
            <TableContainer>
                <Table size="small">
                    <TableHead sx={{ bgcolor: 'action.hover' }}>
                        <TableRow>
                            <TableCell>Task Name</TableCell>
                            <TableCell>Project</TableCell>
                            <TableCell>Status</TableCell>
                            <TableCell>Due Date</TableCell>
                            <TableCell align="right">Action</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {recentTasks.length === 0 ? (
                            <TableRow>
                                <TableCell colSpan={5} align="center" sx={{ py: 3 }}>
                                    <Typography color="text.secondary">No active tasks found</Typography>
                                </TableCell>
                            </TableRow>
                        ) : (
                            recentTasks.map((task) => (
                                <TableRow key={task.id} hover>
                                    <TableCell sx={{ fontWeight: 500 }}>{task.name}</TableCell>
                                    <TableCell>
                                        <Chip 
                                            label={task.project_name || 'Unknown'} 
                                            size="small" 
                                            variant="outlined"
                                            sx={{ fontSize: '0.75rem', height: 20 }}
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <Chip 
                                            label={task.status} 
                                            size="small" 
                                            color={getStatusColor(task.status)}
                                            variant="outlined"
                                        />
                                    </TableCell>
                                    <TableCell>{safeFormat(task.end_date, 'MMM d')}</TableCell>
                                    <TableCell align="right">
                                        <Button 
                                            size="small" 
                                            onClick={() => navigate(`/tasks/${task.id}`)}
                                        >
                                            Details
                                        </Button>
                                    </TableCell>
                                </TableRow>
                            ))
                        )}
                    </TableBody>
                </Table>
            </TableContainer>
        </Paper>
    );
};

