import React, { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Box, Typography, Paper, Tooltip, Zoom, Alert } from '@mui/material';
import { addDays, format, differenceInDays, min, max, isValid, parseISO } from 'date-fns';
import { getSummaryGanttData } from '../../services/projects'; // Assuming this service call exists
import { Project } from '../../types/project'; // Import Project type
import { Task } from '../../types/task'; // Import Task type

interface GanttItem {
    id: string | number;
    name: string;
    start: Date;
    end: Date;
    status: string;
    type: 'Project' | 'Task' | 'Subtask';
    color: string;
    parentName?: string; // For tasks/subtasks, to show their parent project/task
}

const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
        case 'completed': return '#4caf50';
        case 'in progress': return '#2196f3';
        case 'review': return '#ff9800';
        case 'on hold': return '#d32f2f'; // Red for on hold
        default: return '#9e9e9e';
    }
};

const safeDate = (d: string | undefined, fallback: Date): Date => {
    if (!d) return fallback;
    const parsed = parseISO(d);
    return isValid(parsed) ? parsed : fallback;
};

const DashboardGantt: React.FC = () => {
    const { data: projects, isLoading, error } = useQuery<Project[]>({
        queryKey: ['summaryGanttData'],
        queryFn: getSummaryGanttData, // Fetch aggregated data
    });

    const { processedItems, minDate, totalDays } = useMemo(() => {
        if (!projects || projects.length === 0) return { processedItems: [], minDate: new Date(), totalDays: 0 };

        const items: GanttItem[] = [];
        const itemDates: Date[] = [];

        projects.forEach(p => {
            const projectStart = safeDate(p.start_date, new Date());
            const projectEnd = safeDate(p.end_date, addDays(projectStart, 7)); // Default to 7 days if no end
            itemDates.push(projectStart, projectEnd);
            items.push({ 
                id: `proj-${p.id}`, 
                name: p.name, 
                start: projectStart, 
                end: projectEnd, 
                status: p.status, 
                type: 'Project',
                color: getStatusColor(p.status)
            });

            p.tasks?.forEach((t: Task & { project_name?: string }) => { // Task can also have project_name from backend
                const taskStart = safeDate(t.start_date, projectStart);
                const taskEnd = safeDate(t.end_date, addDays(taskStart, 3));
                itemDates.push(taskStart, taskEnd);
                items.push({ 
                    id: `task-${t.id}`, 
                    name: t.name, 
                    start: taskStart, 
                    end: taskEnd, 
                    status: t.status, 
                    type: 'Task',
                    color: getStatusColor(t.status),
                    parentName: p.name
                });

                t.subtasks?.forEach((s: any) => { // Subtask doesn't have a direct type here
                    const subtaskStart = safeDate(s.start_date, taskStart);
                    const subtaskEnd = safeDate(s.end_date, addDays(subtaskStart, 1));
                    itemDates.push(subtaskStart, subtaskEnd);
                    items.push({ 
                        id: `sub-${s.id}`, 
                        name: s.name, 
                        start: subtaskStart, 
                        end: subtaskEnd, 
                        status: s.status, 
                        type: 'Subtask',
                        color: getStatusColor(s.status),
                        parentName: t.name
                    });
                });
            });
        });

        if (itemDates.length === 0) return { processedItems: [], minDate: new Date(), totalDays: 0 };

        const minD = min(itemDates);
        const maxD = addDays(max(itemDates), 2); // Buffer
        const days = differenceInDays(maxD, minD) || 1;

        return { processedItems: items.sort((a,b) => a.start.getTime() - b.start.getTime()), minDate: minD, totalDays: days };
    }, [projects]);

    if (isLoading) {
        return <Typography>Loading summary Gantt...</Typography>;
    }

    if (error) {
        return <Alert severity="error">Error loading summary Gantt: {error.message}</Alert>;
    }

    if (!projects || projects.length === 0 || processedItems.length === 0) {
        return (
            <Paper sx={{ p: 4, textAlign: 'center', borderRadius: 2, bgcolor: 'background.default', mt: 4 }}>
                <Typography color="text.secondary">No projects or tasks with dates to display in Gantt chart.</Typography>
            </Paper>
        );
    }

    return (
        <Paper sx={{ p: 3, mb: 4, overflow: 'hidden', borderRadius: 3, boxShadow: 3 }}>
            <Typography variant="h6" gutterBottom fontWeight="bold" sx={{ mb: 3 }}>
                All Project Timeline Summary
            </Typography>

            <Box sx={{ overflowX: 'auto', pb: 2 }}>
                <Box sx={{ minWidth: 800, position: 'relative' }}>

                    {/* Header: Month/Day Ticks */}
                    <Box sx={{ display: 'flex', borderBottom: '1px solid #eee', mb: 2, pb: 1 }}>
                        <Box sx={{ width: 200, flexShrink: 0, fontWeight: 'bold', color: 'text.secondary' }}>Item</Box>
                        <Box sx={{ flexGrow: 1, position: 'relative', height: 24 }}>
                            {Array.from({ length: totalDays > 30 ? Math.ceil(totalDays / 30) + 1 : totalDays }).map((_, i) => {
                                const tickDate = addDays(minDate, i * (totalDays > 30 ? 30 : 1)); // Show monthly or daily ticks
                                const left = (differenceInDays(tickDate, minDate) / totalDays) * 100;
                                if (left > 100) return null;
                                return (
                                    <Typography key={i} variant="caption" sx={{ position: 'absolute', left: `${left}%`, transform: 'translateX(-50%)', color: 'text.disabled' }}>
                                        {isValid(tickDate) ? format(tickDate, totalDays > 30 ? 'MMM yy' : 'MMM d') : ''}
                                    </Typography>
                                );
                            })}
                        </Box>
                    </Box>

                    {/* Rows */}
                    {processedItems.map((item) => {
                        const startOffset = differenceInDays(item.start, minDate);
                        const duration = differenceInDays(item.end, item.start) || 1;
                        const leftPercent = Math.max(0, (startOffset / totalDays) * 100);
                        const widthPercent = Math.min(100 - leftPercent, (duration / totalDays) * 100);

                        return (
                            <Box key={item.id} sx={{ display: 'flex', alignItems: 'center', mb: 1.5, height: 32, '&:hover': { bgcolor: 'action.hover', borderRadius: 1 } }}>
                                {/* Label */}
                                <Box sx={{ width: 200, flexShrink: 0, pr: 2, display: 'flex', alignItems: 'center' }}>
                                    <Typography variant="body2" noWrap sx={{
                                        fontWeight: item.type === 'Project' ? 600 : (item.type === 'Task' ? 500 : 400),
                                        pl: item.type === 'Subtask' ? 4 : (item.type === 'Task' ? 2 : 0),
                                        color: item.type === 'Subtask' ? 'text.secondary' : 'text.primary'
                                    }}>
                                        {item.type === 'Subtask' && '↳ '} {item.name}
                                        {item.parentName && item.type !== 'Project' && (
                                            <Typography variant="caption" color="text.disabled" sx={{ ml: 0.5 }}>
                                                ({item.parentName})
                                            </Typography>
                                        )}
                                    </Typography>
                                </Box>

                                {/* Bar */}
                                <Box sx={{ flexGrow: 1, position: 'relative', height: '100%' }}>
                                    <Tooltip
                                        title={
                                            <Box sx={{ p: 0.5 }}>
                                                <Typography variant="subtitle2">{item.name}</Typography>
                                                <Typography variant="caption" display="block">
                                                    {item.type} • {isValid(item.start) ? format(item.start, 'MMM d') : '?'} - {isValid(item.end) ? format(item.end, 'MMM d') : '?'}
                                                </Typography>
                                                <Typography variant="caption">{item.status}</Typography>
                                            </Box>
                                        }
                                        TransitionComponent={Zoom}
                                        arrow
                                    >
                                        <Box sx={{
                                            position: 'absolute',
                                            left: `${leftPercent}%`,
                                            width: `${Math.max(widthPercent, 0.5)}%`,
                                            height: item.type === 'Project' ? 24 : 20,
                                            top: item.type === 'Project' ? 4 : 6,
                                            bgcolor: item.color,
                                            borderRadius: 4,
                                            cursor: 'pointer',
                                            transition: 'width 0.3s, left 0.3s',
                                            boxShadow: 1,
                                            '&:hover': { filter: 'brightness(1.1)', transform: 'scaleY(1.1)' }
                                        }} />
                                    </Tooltip>
                                </Box>
                            </Box>
                        );
                    })}
                </Box>
            </Box>
        </Paper>
    );
};

