import React, { useState, useEffect } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    Box,
    Alert,
    Grid,
    MenuItem,
    Typography,
    Select,
    InputLabel,
    FormControl,
    Slider,
    CircularProgress, // Import CircularProgress
    Autocomplete,     // Import Autocomplete
    Chip              // Import Chip
} from '@mui/material';
import { updateSubtask, Subtask } from '../../services/subtasks';
import { User } from '../../types/user'; // User interface moved to types/user
import { Tag } from '../../types/tag'; // Import Tag type
import { Topic } from '../../types/topic'; // Import Topic type
import { getTags, getTopics } from '../../services/adminService'; // Import services to fetch tags/topics
import { useQuery } from '@tanstack/react-query'; // Import useQuery

interface SubtaskEditorProps {
    open: boolean;
    onClose: () => void;
    subtask: Subtask;
    onSubtaskUpdated: () => void;
    users: User[]; // Pass users list for owner selection
    currentTaskSubtasks: Subtask[]; // Pass all subtasks of the current task for parent selection
}

const SubtaskEditor: React.FC<SubtaskEditorProps> = ({ open, onClose, subtask, onSubtaskUpdated, users, currentTaskSubtasks }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [ownerId, setOwnerId] = useState<number | ''>('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [status, setStatus] = useState('Not Started');
    const [progress, setProgress] = useState<number>(0);
    const [selectedTags, setSelectedTags] = useState<Tag[]>([]);
    const [selectedTopics, setSelectedTopics] = useState<Topic[]>([]);
    const [parentSubtaskId, setParentSubtaskId] = useState<number | undefined>(undefined);

    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const statuses = ['Not Started', 'In Progress', 'Completed', 'On Hold'];

    // Helper to check if a subtask is a descendant of another
    const isDescendant = (potentialDescendant: Subtask, potentialAncestorId: number): boolean => {
        let current: Subtask | undefined = potentialDescendant;
        while (current) {
            const parentId = current.parent_subtask_id;
            if (parentId === potentialAncestorId) {
                return true;
            }
            if (parentId) {
                current = currentTaskSubtasks.find(s => s.id === parentId);
            } else {
                current = undefined;
            }
        }
        return false;
    };

    const availableParentSubtasks = currentTaskSubtasks.filter(s =>
        s.id !== subtask.id && !isDescendant(s, subtask.id)
    );

    // Fetch available tags and topics
    const { data: availableTags, isLoading: isLoadingTags } = useQuery<Tag[]>({
        queryKey: ['tags'],
        queryFn: getTags,
        enabled: open, // Only fetch when modal is open
    });

    const { data: availableTopics, isLoading: isLoadingTopics } = useQuery<Topic[]>({
        queryKey: ['topics'],
        queryFn: getTopics,
        enabled: open, // Only fetch when modal is open
    });

    const formLoading = loading || isLoadingTags || isLoadingTopics;

    useEffect(() => {
        if (subtask && open) {
            setName(subtask.name || '');
            setDescription(subtask.description || '');
            setOwnerId(subtask.owner_id || '');
            setStartDate(subtask.start_date ? subtask.start_date.split('T')[0] : '');
            setEndDate(subtask.end_date ? subtask.end_date.split('T')[0] : '');
            setStatus(subtask.status || 'Not Started');
            setProgress(subtask.progress || 0);
            setSelectedTags(subtask.tags || []);
            setSelectedTopics(subtask.topics || []);
            setParentSubtaskId(subtask.parent_subtask_id || undefined);
        }
    }, [subtask, open]);

    const handleSubmit = async () => {
        if (!name.trim()) {
            setError('Subtask name is required');
            return;
        }

        setLoading(true);
        setError('');

        try {
            await updateSubtask(subtask.id, {
                name,
                description: description || undefined,
                owner_id: ownerId === '' ? undefined : Number(ownerId),
                start_date: startDate ? new Date(startDate).toISOString() : undefined,
                end_date: endDate ? new Date(endDate).toISOString() : undefined,
                status,
                progress,
                tag_ids: selectedTags.map(tag => tag.id),
                topic_ids: selectedTopics.map(topic => topic.id),
                parent_subtask_id: parentSubtaskId,
                // Only set parent_task_id if parent_subtask_id is undefined, otherwise it should be derived from the parent subtask
                parent_task_id: parentSubtaskId === undefined ? subtask.parent_task_id : undefined 
            });
            onSubtaskUpdated();
            onClose();
        } catch (err) {
            console.error(err);
            setError('Failed to update subtask');
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            fullWidth
            PaperProps={{
                sx: { borderRadius: 2 }
            }}
        >
            <DialogTitle sx={{ fontWeight: 'bold' }}>Edit Subtask: {subtask?.name}</DialogTitle>
            <DialogContent>
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                {formLoading && <CircularProgress size={20} sx={{ mr: 1 }} />}
                <Box sx={{ mt: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <TextField
                        autoFocus
                        label="Subtask Name"
                        fullWidth
                        variant="outlined"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        disabled={loading}
                        required
                    />
                    <TextField
                        label="Description"
                        fullWidth
                        multiline
                        rows={2}
                        variant="outlined"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        disabled={loading}
                    />
                    <FormControl fullWidth>
                        <InputLabel>Owner</InputLabel>
                        <Select
                            value={ownerId}
                            label="Owner"
                            onChange={(e) => setOwnerId(Number(e.target.value))}
                            disabled={loading}
                        >
                            <MenuItem value=""><em>None</em></MenuItem>
                            {users.map((u) => (
                                <MenuItem key={u.id} value={u.id}>{u.email}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <TextField
                                label="Start Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={startDate}
                                onChange={(e) => setStartDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="End Date"
                                type="date"
                                fullWidth
                                InputLabelProps={{ shrink: true }}
                                value={endDate}
                                onChange={(e) => setEndDate(e.target.value)}
                                disabled={loading}
                            />
                        </Grid>
                    </Grid>
                    <FormControl fullWidth>
                        <InputLabel>Status</InputLabel>
                        <Select
                            value={status}
                            label="Status"
                            onChange={(e) => setStatus(e.target.value)}
                            disabled={loading}
                        >
                            {statuses.map((option) => (
                                <MenuItem key={option} value={option}>
                                    {option}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <Box>
                        <Typography variant="caption" gutterBottom>Progress: {progress}%</Typography>
                        <Slider
                            value={progress}
                            onChange={(_, val) => setProgress(val as number)}
                            aria-labelledby="progress-slider"
                            min={0}
                            max={100}
                            step={1}
                            valueLabelDisplay="auto"
                            disabled={loading}
                        />
                    </Box>

                    <Autocomplete
                        id="subtask-parent-select"
                        options={availableParentSubtasks}
                        getOptionLabel={(option) => option.name}
                        value={availableParentSubtasks.find(s => s.id === parentSubtaskId) || null}
                        onChange={(_, newValue) => setParentSubtaskId(newValue ? Number(newValue.id) : undefined)}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Parent Subtask (Optional)"
                                placeholder="Select parent subtask"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />

                    <Autocomplete
                        multiple
                        id="subtask-tags-select"
                        options={availableTags || []}
                        getOptionLabel={(option) => option.name}
                        value={selectedTags}
                        onChange={(_, newValue) => setSelectedTags(newValue)}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => (
                                <Chip
                                    variant="outlined"
                                    label={option.name}
                                    sx={{ bgcolor: option.color || undefined, color: option.color ? 'white' : 'black' }}
                                    {...getTagProps({ index })}
                                    key={option.id}
                                />
                            ))
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Tags"
                                placeholder="Select tags"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />

                    <Autocomplete
                        multiple
                        id="subtask-topics-select"
                        options={availableTopics || []}
                        getOptionLabel={(option) => option.name}
                        value={selectedTopics}
                        onChange={(_, newValue) => setSelectedTopics(newValue)}
                        renderTags={(value, getTagProps) =>
                            value.map((option, index) => (
                                <Chip
                                    variant="outlined"
                                    label={option.name}
                                    {...getTagProps({ index })}
                                    key={option.id}
                                />
                            ))
                        }
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                variant="outlined"
                                label="Topics"
                                placeholder="Select topics"
                                disabled={formLoading}
                            />
                        )}
                        sx={{ mt: 2 }}
                    />
                </Box>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default SubtaskEditor;

import { Dependency } from './dependency';
import { Tag } from './tag';
import { Topic } from './topic';

export interface SubtaskBase {
    name: string;
    description?: string;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    progress?: number;
    status: string;
}

export interface SubtaskCreate extends SubtaskBase {
    tag_ids?: number[];
    topic_ids?: number[];
}

export interface SubtaskUpdate extends Partial<SubtaskBase> {
    tag_ids?: number[];
    topic_ids?: number[];
    parent_subtask_id?: number;
    parent_task_id?: number;
}

export interface Subtask extends SubtaskBase {
    id: number;
    parent_task_id?: number; // Nullable if nested under another subtask
    parent_subtask_id?: number; // New field for nesting
    created_at?: string;
    updated_at?: string;
    tags?: Tag[];
    topics?: Topic[];
    dependencies_as_prerequisite?: Dependency[];
    dependencies_as_dependent?: Dependency[];
    nested_subtasks?: Subtask[]; // Recursive field
}

import api from './api';
import { Subtask, SubtaskCreate, SubtaskUpdate } from '../types/subtask'; 
export type { Subtask, SubtaskCreate, SubtaskUpdate }; 

export const getSubtasks = async (taskId: number, parentSubtaskId?: number): Promise<Subtask[]> => {
    // Modify this to fetch based on parent_task_id OR parent_subtask_id
    let url = `/tasks/${taskId}/subtasks/`;
    if (parentSubtaskId) {
        url += `?parent_subtask_id=${parentSubtaskId}`;
    }
    const response = await api.get<Subtask[]>(url);
    return response.data;
};

export const createSubtask = async (
    parentTaskId: number | undefined, 
    parentSubtaskId: number | undefined, 
    subtaskData: SubtaskCreate
): Promise<Subtask> => {
    // Backend requires SubtaskCreate schema: name (mapped from title), owner_id
    const payload: any = {
        name: subtaskData.name,
        description: subtaskData.description,
        owner_id: subtaskData.owner_id,
        start_date: subtaskData.start_date,
        end_date: subtaskData.end_date,
        status: subtaskData.status,
        progress: subtaskData.progress,
        tag_ids: subtaskData.tag_ids,
        topic_ids: subtaskData.topic_ids,
    };

    let url = '';
    if (parentTaskId) {
        url = `/tasks/${parentTaskId}/subtasks/`;
        // Pass parent_subtask_id as query param if it exists
        if (parentSubtaskId) {
            url += `?parent_subtask_id=${parentSubtaskId}`;
        }
    } else if (parentSubtaskId) {
        // This case would mean creating a subtask directly under a subtask,
        // but the current backend router still links to a task.
        // The backend `create_subtask_for_task` needs a task_id path param.
        // We will assume that if parentSubtaskId is given, its parent task ID will be passed as taskId.
        // This logic needs to be refined if the backend ever supports direct subtask creation endpoints.
        // For now, if creating a sub-subtask, we always need the grand-parent task_id.
        // The backend `create_subtask_for_task` can handle parent_subtask_id in query.
        throw new Error("Cannot create subtask directly under another subtask without parent task ID. Use grand-parent task ID.");
    } else {
        throw new Error("Must provide either parentTaskId or parentSubtaskId.");
    }
    
    // Explicitly set parent_task_id/parent_subtask_id in payload if not already set by query param
    // This is for the backend Pydantic model
    if (parentTaskId) payload.parent_task_id = parentTaskId;
    if (parentSubtaskId) payload.parent_subtask_id = parentSubtaskId;


    const response = await api.post<Subtask>(url, payload);
    return response.data;
};

export const updateSubtask = async (subtaskId: number, updates: SubtaskUpdate): Promise<Subtask> => {
    const response = await api.put(`/subtasks/${subtaskId}`, updates);
    return response.data;
};

export const deleteSubtask = async (subtaskId: number): Promise<void> => {
    await api.delete(`/subtasks/${subtaskId}`);
};

