import React from 'react';
import { List, ListItem, ListItemText, ListItemSecondaryAction, IconButton, Checkbox, ListItemIcon, Box, Typography, Chip } from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import { Subtask } from '../../types/subtask';
import { User } from '../../types/user';
import { Tag } from '../../types/tag';
import { Topic } from '../../types/topic';


interface SubtaskHierarchyRendererProps {
    subtasks: Subtask[];
    level?: number;
    onToggleSubtask: (subtask: Subtask) => void;
    onDeleteSubtask: (subtaskId: number | string) => void;
    onEditSubtask: (subtask: Subtask) => void;
    users: User[]; // Pass users for owner display
}

const SubtaskHierarchyRenderer: React.FC<SubtaskHierarchyRendererProps> = ({
    subtasks,
    level = 0,
    onToggleSubtask,
    onDeleteSubtask,
    onEditSubtask,
    users
}) => {
    const getUserName = (id: number) => {
        const user = users.find((u: any) => u.id === id);
        return user ? user.email : 'Unknown User';
    };

    return (
        <List dense disablePadding>
            {subtasks.map((sub) => (
                <Box key={sub.id} sx={{ pl: level * 2 }}>
                    <ListItem divider={level === 0}>
                        <ListItemIcon>
                            <Checkbox
                                edge="start"
                                checked={sub.status === 'Completed'}
                                onChange={() => onToggleSubtask(sub)}
                                tabIndex={-1}
                                disableRipple
                            />
                        </ListItemIcon>
                        <ListItemText
                            primary={
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Typography 
                                        variant="body2" 
                                        sx={{ 
                                            textDecoration: sub.status === 'Completed' ? 'line-through' : 'none',
                                            opacity: sub.status === 'Completed' ? 0.8 : 1
                                        }}
                                    >
                                        {sub.name}
                                    </Typography>
                                    <Chip label={sub.status} size="small" variant="outlined" />
                                </Box>
                            }
                            secondary={
                                <React.Fragment>
                                    <Typography component="span" variant="caption" sx={{ display: 'block' }}>
                                        Owner: {getUserName(sub.owner_id)}
                                    </Typography>
                                    {sub.description && (
                                        <Typography component="span" variant="caption" sx={{ mr: 1 }}>
                                            {sub.description}
                                        </Typography>
                                    )}
                                    {sub.start_date || sub.end_date
                                        ? `Dates: ${sub.start_date?.split('T')[0] || '?'} - ${sub.end_date?.split('T')[0] || '?'}`
                                        : "No dates set"}
                                    <br />
                                    <Typography component="span" variant="caption" sx={{ mr: 1 }}>
                                        Progress: {sub.progress}%
                                    </Typography>
                                    {sub.tags && sub.tags.length > 0 && (
                                        <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mt: 0.5 }}>
                                            {sub.tags.map((tag: Tag) => (
                                                <Chip
                                                    key={tag.id}
                                                    label={tag.name}
